<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap.php';
Auth::requireApprovedSeller();
$pdo=db(); $sellerId=(int)Auth::userId(); $orderId=(int)($_GET['id'] ?? 0); $error=flash('error'); $success=flash('success');
$stmt=$pdo->prepare('SELECT o.*,u.name customer_name,u.email customer_email,u.phone customer_phone FROM orders o INNER JOIN users u ON u.id=o.customer_id WHERE o.id=? AND EXISTS(SELECT 1 FROM order_items x WHERE x.order_id=o.id AND x.seller_id=?) LIMIT 1');
$stmt->execute([$orderId,$sellerId]); $order=$stmt->fetch(); if(!$order){http_response_code(404);exit('Order not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf($_POST['_csrf']??null); $itemId=(int)($_POST['item_id']??0); $to=trim((string)($_POST['status']??'')); $note=trim((string)($_POST['note']??''));
 $pdo->beginTransaction();
 try{
  $q=$pdo->prepare('SELECT oi.*,o.status order_status FROM order_items oi INNER JOIN orders o ON o.id=oi.order_id WHERE oi.id=? AND oi.order_id=? AND oi.seller_id=? FOR UPDATE'); $q->execute([$itemId,$orderId,$sellerId]); $item=$q->fetch();
  if(!$item) throw new RuntimeException('Order item not found.');
  if(!OrderManager::sellerCanTransition((string)$item['fulfillment_status'],$to)) throw new RuntimeException('That status change is not allowed from the current status.');
  $pdo->prepare('UPDATE order_items SET fulfillment_status=?,seller_note=?,updated_at=NOW() WHERE id=?')->execute([$to,$note!==''?$note:null,$itemId]);
  $newStatus=OrderManager::recalculateAndRecord($orderId,$sellerId,'Seller fulfillment update.');
  $pdo->commit(); flash('success','Order item updated. Order status is now '.ucwords(str_replace('_',' ',$newStatus)).'.'); redirect('/seller/order.php?id='.$orderId);
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=APP_ENV==='development'?$e->getMessage():'Unable to update this order.';}
}
$stmt=$pdo->prepare('SELECT oi.*,p.name FROM order_items oi INNER JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? AND oi.seller_id=? ORDER BY oi.id');$stmt->execute([$orderId,$sellerId]);$items=$stmt->fetchAll();
$shipping=json_decode((string)($order['shipping_address']??''),true)?:[];
function sellerOrderBadge2(string $s):string{return match($s){'completed'=>'success','cancelled','refunded'=>'danger','shipped'=>'info',default=>'warning'};}
?>
<!doctype html><html lang="en"><head><link rel="icon" href="<?= e(url('/assets/images/favicon-32.png')) ?>"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e((string)$order['order_number'])?> · Seller · DogoFlow</title><?php require __DIR__ . '/../partials/tailwind.php'; ?></head><body><main class="container" style="padding:42px 0 80px"><a href="<?=e(url('/seller/orders.php'))?>" style="color:#0088EE;font-weight:800;text-decoration:none">← Back to seller orders</a><div class="page-heading" style="margin-top:12px"><div><h1><?=e((string)$order['order_number'])?></h1><p style="color:#64748B">Customer: <?=e((string)$order['customer_name'])?> · <?=e((string)$order['customer_phone'])?></p></div><span class="badge-df <?=e(sellerOrderBadge2((string)$order['status']))?>"><?=e(ucwords(str_replace('_',' ',(string)$order['status'])))?></span></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><section class="card"><h2 style="margin-top:0">Your items</h2><?php foreach($items as $i): ?><div style="padding:18px 0;border-bottom:1px solid #E2E8F0"><div style="display:flex;justify-content:space-between;gap:15px;align-items:flex-start"><div><strong><?=e((string)$i['name'])?></strong><div style="color:#64748B;font-size:.85rem">Qty <?= (int)$i['quantity'] ?> · GH₵ <?=number_format((float)$i['subtotal'],2)?></div></div><span class="badge-df <?=e(sellerOrderBadge2((string)$i['fulfillment_status']))?>"><?=e(ucwords(str_replace('_',' ',(string)$i['fulfillment_status'])))?></span></div><?php if((string)$i['fulfillment_status']!=='completed'): ?><form method="post" style="margin-top:14px;display:flex;gap:10px;flex-wrap:wrap;align-items:end"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="item_id" value="<?= (int)$i['id'] ?>"><div><label class="checkout-label">Next status</label><select class="checkout-input" name="status"><?php foreach(['processing','shipped','completed'] as $st): if(OrderManager::sellerCanTransition((string)$i['fulfillment_status'],$st)): ?><option value="<?=e($st)?>"><?=e(ucwords($st))?></option><?php endif;endforeach;?></select></div><div style="flex:1;min-width:220px"><label class="checkout-label">Seller note</label><input class="checkout-input" name="note" placeholder="Optional delivery/fulfillment note"></div><button class="btn btn-primary" type="submit">Update</button></form><?php endif; ?></div><?php endforeach;?></section><div class="checkout-grid" style="margin-top:18px"><div class="card"><h2 style="margin-top:0">Delivery</h2><p><?=e((string)($shipping['full_name']??''))?><br><?=e((string)($shipping['phone']??''))?><br><?=e((string)($shipping['address']??''))?><br><?=e((string)($shipping['city']??''))?>, <?=e((string)($shipping['region']??''))?></p></div><div class="card"><h2 style="margin-top:0">Order total</h2><div class="checkout-total"><strong>Total</strong><strong style="color:#0088EE">GH₵ <?=number_format((float)$order['total'],2)?></strong></div></div></div></main></body></html>
